//! Parity with the TS codecs through the golden vectors in `tests/vectors`
//! (generated by `cli/scripts/desktop-vectors.ts`): Rust must produce the TS
//! bytes and accept or reject exactly the inputs TS does, with the same error.

use std::fmt::Debug;
use std::str::FromStr;

use alloy_primitives::{Address, B256, U256, hex};
use qop_desktop::registry::{self, RegistryError};
use qop_desktop::wire::*;
use serde_json::Value;

// --- Helpers -----------------------------------------------------------------

fn load(name: &str) -> Value {
    let path = format!("{}/tests/vectors/{name}", env!("CARGO_MANIFEST_DIR"));

    serde_json::from_str(&std::fs::read_to_string(path).expect("vector file")).expect("vector JSON")
}

fn list(value: &Value) -> &[Value] {
    value.as_array().expect("array of cases")
}

fn text(value: &Value) -> &str {
    value.as_str().expect("string")
}

fn bytes(value: &Value) -> Vec<u8> {
    hex::decode(text(value)).expect("hex")
}

fn b256(value: &Value) -> B256 {
    B256::from_str(text(value)).expect("bytes32")
}

fn u256(value: &Value) -> U256 {
    U256::from_str_radix(text(value), 10).expect("decimal")
}

fn u64_of(value: &Value) -> u64 {
    value
        .as_u64()
        .or_else(|| text(value).parse().ok())
        .expect("u64")
}

fn address(value: &Value) -> Address {
    Address::from_str(text(value)).expect("address")
}

fn lower(value: impl AsRef<[u8]>) -> String {
    hex::encode_prefixed(value)
}

/// What TS `JSON.stringify` emits for a decoded value: every TS struct
/// declares its keys in byte order, which is serde_json's map order.
fn canonical(value: &Value) -> Vec<u8> {
    serde_json::to_vec(value).expect("JSON")
}

/// A decoder input: `{ text, padTo? }` or `{ hex }`.
fn input(input: &Value) -> Vec<u8> {
    if let Some(hex) = input.get("hex") {
        return bytes(hex);
    }

    let mut bytes = text(&input["text"]).as_bytes().to_vec();

    if let Some(length) = input.get("padTo").and_then(Value::as_u64) {
        bytes.resize(usize::try_from(length).expect("length"), b' ');
    }

    bytes
}

/// Assert Rust agrees with TS on success, or on the error kind. Returns the
/// Rust value when both succeeded.
fn agree<T, E: Debug>(
    case: &Value,
    result: Result<T, E>,
    kind: impl Fn(&E) -> &'static str,
) -> Option<T> {
    let name = &case["name"];

    match (case["ok"].as_bool().expect("ok flag"), result) {
        (true, Ok(value)) => Some(value),
        (false, Err(error)) => {
            assert_eq!(kind(&error), text(&case["error"]), "{name}: error kind");
            None
        }
        (true, Err(error)) => panic!("{name}: TS accepts, Rust rejects with {error:?}"),
        (false, Ok(_)) => panic!("{name}: TS rejects ({}), Rust accepts", case["error"]),
    }
}

fn pairing_kind(error: &PairingError) -> &'static str {
    match error {
        PairingError::Expired => "expired",
        PairingError::Frame => "frame",
        PairingError::Offer => "offer",
        PairingError::Oversized => "oversized",
        PairingError::Version => "version",
    }
}

fn chat_kind(error: &ChatError) -> &'static str {
    match error {
        ChatError::Invalid => "invalid",
        ChatError::Oversized => "oversized",
    }
}

fn sync_kind(error: &SyncCodecError) -> &'static str {
    match error {
        SyncCodecError::Frame => "frame",
        SyncCodecError::Oversized => "oversized",
    }
}

/// TS reports viem's ABI failures as `rpc` and schema failures as `decode`.
fn registry_kind(error: &RegistryError) -> &'static str {
    match error {
        RegistryError::Abi => "rpc",
        RegistryError::Decode => "decode",
        RegistryError::InvalidHandle => "invalid",
    }
}

// Builders for encoder inputs, deliberately unvalidated so encoders see the
// same invalid values TS was given.

fn domain_from(value: &Value) -> IdentityDomain {
    IdentityDomain {
        chain_id: u256(&value["chainId"]),
        verifying_contract: address(&value["verifyingContract"]),
    }
}

fn intent_from(value: &Value) -> DeviceIntent {
    DeviceIntent {
        deadline: u64_of(&value["deadline"]),
        device_key: b256(&value["deviceKey"]),
        nonce: u256(&value["nonce"]),
        qid: u256(&value["qid"]),
    }
}

fn offer_from(value: &Value) -> PairingOffer {
    PairingOffer {
        addrs: list(&value["addrs"])
            .iter()
            .map(|addr| text(addr).to_owned())
            .collect(),
        chain_id: u256(&value["chainId"]),
        device_key: b256(&value["deviceKey"]),
        expires_at: u64_of(&value["expiresAt"]),
        qid: u256(&value["qid"]),
        registry: address(&value["registry"]),
        secret: b256(&value["secret"]),
        session_id: b256(&value["sessionId"]),
    }
}

fn frame_from(value: &Value) -> ChatFrame {
    ChatFrame {
        from_handle: text(&value["fromHandle"]).to_owned(),
        id: text(&value["id"]).to_owned(),
        sent_at: u64_of(&value["sentAt"]),
        text: text(&value["text"]).to_owned(),
    }
}

fn inbox_record_from(value: &Value) -> InboxRecord {
    InboxRecord {
        frame: frame_from(&value["frame"]),
        from_qid: text(&value["fromQid"]).to_owned(),
        received_at: u64_of(&value["receivedAt"]),
    }
}

fn sync_request_from(value: &Value) -> SyncRequest {
    match text(&value["type"]) {
        "handoff" => {
            let record = &value["record"];

            SyncRequest::Handoff {
                composed_by: b256(&value["composedBy"]),
                record: OutboxRecord {
                    attempts: u64_of(&record["attempts"]),
                    frame: frame_from(&record["frame"]),
                    last_error: record["lastError"].as_str().map(str::to_owned),
                    next_attempt_at: u64_of(&record["nextAttemptAt"]),
                    queued_at: u64_of(&record["queuedAt"]),
                    status: match text(&record["status"]) {
                        "queued" => OutboxStatus::Queued,
                        "sent" => OutboxStatus::Sent,
                        _ => OutboxStatus::Failed,
                    },
                    to_handle: text(&record["toHandle"]).to_owned(),
                    to_qid: text(&record["toQid"]).to_owned(),
                    updated_at: u64_of(&record["updatedAt"]),
                },
            }
        }
        "poll" => SyncRequest::Poll {
            ids: list(&value["ids"])
                .iter()
                .map(|id| text(id).to_owned())
                .collect(),
        },
        _ => SyncRequest::Catchup {
            after: u64_of(&value["after"]),
        },
    }
}

fn sync_response_from(value: &Value) -> SyncResponse {
    match text(&value["type"]) {
        "held" => SyncResponse::Held {
            id: text(&value["id"]).to_owned(),
        },
        "receipts" => SyncResponse::Receipts {
            receipts: list(&value["receipts"])
                .iter()
                .map(|receipt| SyncReceipt {
                    delivered_at: u64_of(&receipt["deliveredAt"]),
                    id: text(&receipt["id"]).to_owned(),
                    to_qid: text(&receipt["toQid"]).to_owned(),
                })
                .collect(),
        },
        "inbox" => SyncResponse::Inbox {
            last_seq: u64_of(&value["lastSeq"]),
            records: list(&value["records"])
                .iter()
                .map(|item| SyncInboxItem {
                    record: inbox_record_from(&item["record"]),
                    seq: u64_of(&item["seq"]),
                })
                .collect(),
        },
        _ => SyncResponse::Error {
            reason: match text(&value["reason"]) {
                "conflict" => SyncErrorReason::Conflict,
                "invalid" => SyncErrorReason::Invalid,
                _ => SyncErrorReason::Unavailable,
            },
        },
    }
}

// --- Identity and EIP-712 ----------------------------------------------------

#[test]
fn device_key_peer_id_and_fingerprint() {
    let vectors = load("identity.json");

    for device in list(&vectors["devices"]) {
        let secret: [u8; 32] = bytes(&device["secretKey"])
            .try_into()
            .expect("32-byte secret");
        let device_key = device_key_from_secret(secret);

        assert_eq!(lower(device_key), text(&device["deviceKey"]));
        assert_eq!(
            peer_id_from_device_key(&device_key).to_base58(),
            text(&device["peerId"])
        );
        assert_eq!(
            pairing_fingerprint(&device_key),
            text(&device["fingerprint"])
        );
    }

    for case in list(&vectors["peerIdToDeviceKey"]) {
        let result = device_key_from_peer_id(text(&case["peerId"])).ok_or(());

        if let Some(device_key) = agree(case, result, |()| "invalid") {
            assert_eq!(lower(device_key), text(&case["value"]));
        }
    }
}

#[test]
fn eip712_digest_and_signer_recovery() {
    let vectors = load("eip712.json");
    let domain = domain_from(&vectors["domain"]);

    assert_eq!(
        text(&vectors["domainName"]),
        qop_desktop::wire::eip712::IDENTITY_EIP712_DOMAIN_NAME
    );
    assert_eq!(
        text(&vectors["domainVersion"]),
        qop_desktop::wire::eip712::IDENTITY_EIP712_DOMAIN_VERSION
    );
    assert_eq!(lower(domain.separator()), text(&vectors["domainSeparator"]));

    for case in list(&vectors["addDevice"]) {
        let intent = intent_from(&case["intent"]);
        let signature =
            EcdsaSignature::parse(text(&case["signature"])).expect("canonical signature");

        assert_eq!(
            lower(intent.add_device_digest(&domain).unwrap()),
            text(&case["digest"])
        );
        assert_eq!(
            lower(
                intent
                    .recover_add_device_signer(&domain, &signature)
                    .unwrap()
            ),
            text(&case["signer"])
        );
        assert_eq!(signature.to_hex(), text(&case["signature"]));
    }

    for case in list(&vectors["hashRejections"]) {
        let result = intent_from(&case["intent"]).add_device_digest(&domain_from(&case["domain"]));

        agree(case, result, |_| "hash-add-device-intent");
    }

    let intent = intent_from(&list(&vectors["addDevice"])[0]["intent"]);

    for case in list(&vectors["recover"]) {
        let result = EcdsaSignature::parse(text(&case["signature"]))
            .ok_or(None)
            .and_then(|signature| {
                intent
                    .recover_add_device_signer(&domain, &signature)
                    .map_err(Some)
            });

        let kind = |error: &Option<IntentError>| match error {
            None => "invalid",
            Some(_) => "recover-add-device-intent-signer",
        };

        if let Some(signer) = agree(case, result, kind) {
            assert_eq!(lower(signer), text(&case["value"]));
        }
    }
}

// --- Approval and pairing ----------------------------------------------------

#[test]
fn approval_records() {
    let vectors = load("approval.json");

    for case in list(&vectors["encode"]) {
        let record =
            DeviceActionApproval::decode(&canonical(&case["record"])).expect("valid record");

        assert_eq!(record.encode(), text(&case["json"]).as_bytes());
    }

    for case in list(&vectors["decode"]) {
        if let Some(record) = agree(
            case,
            DeviceActionApproval::decode(text(&case["json"]).as_bytes()),
            |_| "invalid",
        ) {
            assert_eq!(
                record.encode(),
                canonical(&case["value"]),
                "{}",
                case["name"]
            );
        }
    }

    for case in list(&vectors["verify"]) {
        let result = DeviceActionApproval::decode(&canonical(&case["record"]))
            .and_then(|record| record.verify_digest());
        let kind = |error: &ApprovalError| match error {
            ApprovalError::Decode => "invalid",
            ApprovalError::Digest => "digest",
        };

        if let Some(digest) = agree(case, result, kind) {
            assert_eq!(lower(digest), text(&case["value"]));
        }
    }
}

#[test]
fn pairing_offers() {
    let vectors = load("pairing-offer.json");

    for case in list(&vectors["encode"]) {
        if let Some(payload) = agree(case, offer_from(&case["offer"]).encode(), pairing_kind) {
            assert_eq!(payload, text(&case["value"]), "{}", case["name"]);
        }
    }

    for case in list(&vectors["decode"]) {
        let result = PairingOffer::decode(text(&case["input"]), u64_of(&case["now"]));

        if let Some(offer) = agree(case, result, pairing_kind) {
            assert_eq!(offer, offer_from(&case["value"]), "{}", case["name"]);
        }
    }
}

#[test]
fn pairing_frames() {
    let vectors = load("pairing-frame.json");

    for case in list(&vectors["encode"]) {
        let frame = PairingFrame::decode(&canonical(&case["frame"])).expect("valid frame");

        if let Some(bytes) = agree(case, frame.encode(), pairing_kind) {
            assert_eq!(bytes, text(&case["value"]).as_bytes());
        }
    }

    for case in list(&vectors["decode"]) {
        if let Some(frame) = agree(
            case,
            PairingFrame::decode(&input(&case["input"])),
            pairing_kind,
        ) {
            assert_eq!(
                frame.encode().unwrap(),
                canonical(&case["value"]),
                "{}",
                case["name"]
            );
        }
    }
}

// --- Chat, sync and API status -----------------------------------------------

#[test]
fn chat_frames_and_acks() {
    let vectors = load("chat.json");
    let frames = &vectors["frames"];
    let acks = &vectors["acks"];

    for case in list(&frames["encode"]) {
        if let Some(bytes) = agree(case, frame_from(&case["frame"]).encode(), chat_kind) {
            assert_eq!(bytes, text(&case["value"]).as_bytes(), "{}", case["name"]);
        }
    }

    for case in list(&frames["decode"]) {
        if let Some(frame) = agree(case, ChatFrame::decode(&input(&case["input"])), chat_kind) {
            assert_eq!(
                frame.encode().unwrap(),
                canonical(&case["value"]),
                "{}",
                case["name"]
            );
        }
    }

    for case in list(&acks["encode"]) {
        let ack = ChatAck {
            ack: text(&case["ack"]["ack"]).to_owned(),
        };

        if let Some(bytes) = agree(case, ack.encode(), chat_kind) {
            assert_eq!(bytes, text(&case["value"]).as_bytes());
        }
    }

    for case in list(&acks["decode"]) {
        if let Some(ack) = agree(case, ChatAck::decode(&input(&case["input"])), chat_kind) {
            assert_eq!(
                ack.encode().unwrap(),
                canonical(&case["value"]),
                "{}",
                case["name"]
            );
        }
    }
}

#[test]
fn sync_requests_and_responses() {
    let vectors = load("sync.json");
    let requests = &vectors["requests"];
    let responses = &vectors["responses"];

    for case in list(&requests["encode"]) {
        if let Some(bytes) = agree(
            case,
            sync_request_from(&case["request"]).encode(),
            sync_kind,
        ) {
            assert_eq!(bytes, text(&case["value"]).as_bytes(), "{}", case["name"]);
        }
    }

    for case in list(&requests["decode"]) {
        if let Some(request) = agree(case, SyncRequest::decode(&input(&case["input"])), sync_kind) {
            assert_eq!(
                request.encode().unwrap(),
                canonical(&case["value"]),
                "{}",
                case["name"]
            );
        }
    }

    for case in list(&responses["encode"]) {
        if let Some(bytes) = agree(
            case,
            sync_response_from(&case["response"]).encode(),
            sync_kind,
        ) {
            assert_eq!(bytes, text(&case["value"]).as_bytes(), "{}", case["name"]);
        }
    }

    for case in list(&responses["decode"]) {
        if let Some(response) = agree(
            case,
            SyncResponse::decode(&input(&case["input"])),
            sync_kind,
        ) {
            assert_eq!(
                response.encode().unwrap(),
                canonical(&case["value"]),
                "{}",
                case["name"]
            );
        }
    }
}

#[test]
fn device_action_status_responses() {
    for case in list(&load("device-action-status.json")) {
        let status = u16::try_from(u64_of(&case["status"])).expect("HTTP status");
        let result = decode_device_action_response(status, &input(&case["body"]));
        let kind = |error: &DeviceActionStatusError| match error {
            DeviceActionStatusError::Decode => "decode",
            DeviceActionStatusError::Missing => "missing",
            DeviceActionStatusError::Network => "network",
        };

        if let Some(record) = agree(case, result, kind) {
            let value = &case["value"];
            let status = format!("{:?}", record.status).to_lowercase();

            assert_eq!(lower(record.digest), text(&value["digest"]));
            assert_eq!(
                record.failure_code.as_deref(),
                value["failureCode"].as_str(),
                "{}",
                case["name"]
            );
            assert_eq!(status, text(&value["status"]));
            assert_eq!(
                record.transaction_hash.map(lower).as_deref(),
                value["transactionHash"].as_str()
            );
        }
    }
}

// --- Registry ----------------------------------------------------------------

#[test]
fn registry_handle_hash_and_calldata() {
    let vectors = load("registry.json");

    for case in list(&vectors["handleHash"]) {
        if let Some(hash) = agree(
            case,
            registry::handle_hash(text(&case["handle"])),
            registry_kind,
        ) {
            assert_eq!(lower(hash), text(&case["value"]));
        }
    }

    for call in list(&vectors["calldata"]) {
        let arg = &list(&call["args"])[0];
        let data = match text(&call["functionName"]) {
            "qidByHandleHash" => {
                assert_eq!(lower(registry::handle_hash("alice").unwrap()), text(arg));
                registry::qid_by_handle_hash_call("alice").unwrap()
            }
            "account" => registry::account_call(u256(arg)),
            "listActiveDevices" => registry::list_active_devices_call(u256(arg)),
            "qidByDeviceKey" => registry::qid_by_device_key_call(&b256(arg)),
            "deviceKeyRemoved" => registry::device_key_removed_call(&b256(arg)),
            other => panic!("unexpected registry read {other}"),
        };

        assert_eq!(lower(data), text(&call["data"]), "{}", call["functionName"]);
    }
}

#[test]
fn registry_responses() {
    let vectors = load("registry.json");

    for case in list(&vectors["qid"]) {
        if let Some(qid) = agree(
            case,
            registry::decode_qid(&bytes(&case["data"])),
            registry_kind,
        ) {
            assert_eq!(
                qid.unwrap_or_default().to_string(),
                text(&case["value"]),
                "{}",
                case["name"]
            );
        }
    }

    for case in list(&vectors["bool"]) {
        if let Some(removed) = agree(
            case,
            registry::decode_bool(&bytes(&case["data"])),
            registry_kind,
        ) {
            assert_eq!(Some(removed), case["value"].as_bool(), "{}", case["name"]);
        }
    }

    for case in list(&vectors["devices"]) {
        if let Some(devices) = agree(
            case,
            registry::decode_active_devices(&bytes(&case["data"])),
            registry_kind,
        ) {
            let expected = list(&case["value"]);

            assert_eq!(devices.len(), expected.len(), "{}", case["name"]);

            for (device, expected) in devices.iter().zip(expected) {
                assert_eq!(lower(device.device_key), text(&expected["deviceKey"]));
                assert_eq!(device.peer_id.to_base58(), text(&expected["peerId"]));
            }
        }
    }

    for case in list(&vectors["account"]) {
        if let Some(account) = agree(
            case,
            registry::decode_account(&bytes(&case["data"])),
            registry_kind,
        ) {
            let value = &case["value"];

            assert_eq!(account.handle, text(&value["handle"]), "{}", case["name"]);
            assert_eq!(account.nonce, u256(&value["nonce"]));
            assert_eq!(lower(account.owner), text(&value["owner"]));
            assert_eq!(
                u64::from(account.owner_version),
                u64_of(&value["ownerVersion"])
            );
            assert_eq!(account.registered_at, u64_of(&value["registeredAt"]));
        }
    }
}
